 bool TryRecoverAtStartup(){foreach(string backup in BackupVault.List(taskPath)){List<TaskItem> candidate;try{candidate=TaskStorage.Read(backup);}catch{continue;}if(MessageBox.Show("当前日程文件无法读取。找到 "+File.GetLastWriteTime(backup).ToString("yyyy-MM-dd HH:mm")+" 的备份（"+candidate.Count+" 项）。\n是否保留当前损坏文件并恢复这个备份？","恢复日程",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)!=MessageBoxResult.Yes)return false;string preserved=Path.Combine(BackupVault.DirectoryFor(taskPath),"unreadable-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff")+".json");File.Copy(taskPath,preserved,false);TaskStorage.Write(taskPath,candidate);tasks=new ObservableCollection<TaskItem>(candidate);foreach(TaskItem task in tasks)task.PropertyChanged+=Changed;return true;}return false;}
 void RefreshFilterPicker(){if(filterPicker==null)return;filterPicker.Items.Clear();foreach(string label in new[]{"全部任务","仅工作","高优先级"}.Concat(savedFilters.Select(x=>x.Name)))filterPicker.Items.Add(new ComboBoxItem{Content=label});filterPicker.SelectedIndex=0;}
 bool MatchesWorkspaceQuery(TaskItem t){
  string q=(searchBox.Text??"").Trim();if(q.Length>0&&!Has(t.Title,q)&&!Has(t.Notes,q)&&!Has(t.Location,q)&&!Has(t.Project,q)&&!Has(t.Tags,q)&&!Has(t.Reviewer,q))return false;
  if(activeFilter!=null){if(!String.IsNullOrWhiteSpace(activeFilter.Category)&&t.Category!=activeFilter.Category)return false;if(!String.IsNullOrWhiteSpace(activeFilter.Project)&&!Has(t.Project,activeFilter.Project))return false;if(!String.IsNullOrWhiteSpace(activeFilter.Tag)&&!Has(t.Tags,activeFilter.Tag))return false;if(t.Priority<activeFilter.MinimumPriority)return false;}
  return true;
 }
 bool FilterWorkspace(TaskItem t){
  if(!MatchesWorkspaceQuery(t))return false;if(mode=="Recycle")return t.IsDeleted;if(t.IsDeleted)return false;
  if(mode=="Review")return t.IsAwaitingReview;if(mode=="Completed")return t.IsDone;
  if(t.IsDone||t.IsAwaitingReview)return false;
  if(mode=="Inbox")return t.Unscheduled;
  if(mode=="Overdue")return PlanningRules.IsDateBefore(t.DeadlineDate,DateTime.Today);
  if(mode=="Upcoming")return PlanningRules.IsDateBefore(t.DeadlineDate,DateTime.Today.AddDays(8))&&!PlanningRules.IsDateBefore(t.DeadlineDate,DateTime.Today);
  if(mode=="Today")return PlanningRules.Occurs(t,DateTime.Today)||t.DeadlineDate==DateTime.Today.ToString("yyyy-MM-dd");
  if(mode=="Focus")return PlanningRules.Occurs(t,DateTime.Today)||t.Priority>=3||PlanningRules.IsDateBefore(t.DeadlineDate,DateTime.Today.AddDays(1));
  return !t.Unscheduled;
 }
 void StampState(TaskItem t){string now=DateTime.Now.ToString("o");if(t.IsAwaitingReview){if(String.IsNullOrEmpty(t.ExecutedAt))t.ExecutedAt=now;if(String.IsNullOrEmpty(t.SubmittedAt))t.SubmittedAt=now;t.CompletedAt="";}else if(t.IsDone){if(String.IsNullOrEmpty(t.ExecutedAt))t.ExecutedAt=now;t.CompletedAt=now;}else{t.CompletedAt="";t.SubmittedAt="";t.FollowUpNotified="";}t.RefreshPlanning();}
