 bool ValidateEditorExtras(){
  foreach(var picker in new[]{editDate,editorDeadline,editorEnd,editorFollowUp,editorUntil}){DateTime parsed;if(!String.IsNullOrWhiteSpace(picker.Text)&&!DateTime.TryParse(picker.Text,out parsed))return EditorProblem("日期无效，请从日历中选择有效日期");}
  int n;if(!Int32.TryParse(editorInterval.Text,out n)||n<1||n>365)return EditorProblem("重复间隔应为 1–365 的整数");
  if(editorLimit.Text.Trim().Length>0&&(!Int32.TryParse(editorLimit.Text,out n)||n<1||n>10000))return EditorProblem("重复次数应为 1–10000 的整数");
  if(editorEstimate.Text.Trim().Length>0&&(!Int32.TryParse(editorEstimate.Text,out n)||n<0||n>1440))return EditorProblem("预计分钟应为 0–1440 的整数");
  DateTime planned=editDate.SelectedDate??DateTime.Today;if(editorEnd.SelectedDate.HasValue&&editorEnd.SelectedDate.Value<planned)return EditorProblem("跨日结束不能早于计划日期");
  if(editorUntil.SelectedDate.HasValue&&editorUntil.SelectedDate.Value<planned)return EditorProblem("重复截止不能早于首次计划日期");
  if(ComboText(editRepeat)=="自定义周"&&!weekdayChoices.Any(x=>x.IsChecked==true))return EditorProblem("请至少选择一个重复星期");
  foreach(string s in (editorExceptions.Text??"").Split(new[]{',','，',';','；',' ','\r','\n'},StringSplitOptions.RemoveEmptyEntries)){DateTime d;if(!PlanningRules.TryDate(s,out d))return EditorProblem("跳过日期请使用 yyyy-MM-dd 格式");}
  return true;
 }
 bool EditorProblem(string message){editorError.Text=message;editorError.Visibility=Visibility.Visible;return false;}
 void SaveEditorExtras(TaskItem t){t.Unscheduled=editorUnscheduled.IsChecked==true;t.DeadlineDate=GetDate(editorDeadline);t.EndDate=GetDate(editorEnd);t.Project=editorProject.Text.Trim();t.Tags=editorTags.Text.Trim();t.Priority=editorPriority.SelectedIndex;int n;t.EstimateMinutes=Int32.TryParse(editorEstimate.Text,out n)?n:0;t.Reviewer=editorReviewer.Text.Trim();t.ReviewNotes=editorReviewNotes.Text.Trim();if(t.FollowUpDate!=GetDate(editorFollowUp))t.FollowUpNotified="";t.FollowUpDate=GetDate(editorFollowUp);t.RepeatInterval=Int32.Parse(editorInterval.Text);t.RepeatFromCompletion=editorRepeatBase.SelectedIndex==1;t.RepeatWeekdays=String.Join(",",weekdayChoices.Where(x=>x.IsChecked==true).Select(x=>Convert.ToString(x.Tag)));t.RepeatUntil=GetDate(editorUntil);t.RepeatLimit=Int32.TryParse(editorLimit.Text,out n)?n:0;t.RepeatExceptions=editorExceptions.Text.Trim();t.Checklist=editorChecklist.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>new ChecklistItem{Done=x.TrimStart().StartsWith("[x]",StringComparison.OrdinalIgnoreCase),Text=System.Text.RegularExpressions.Regex.Replace(x.Trim(),@"^\[(?:x|X| )?\]\s*","")}).Where(x=>x.Text.Length>0).ToList();t.Links=editorLinks.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Distinct().ToList();if(!t.RecurrenceCreated)t.RecurrenceStart=t.DueDate;PlanningRules.Normalize(t);t.RefreshPlanning();}

 void RefreshDetailExtras(TaskItem t){
  if(detailExtra==null)return;PlanningRules.Normalize(t);detailExtra.Children.Clear();
  Find<Button>("DetailEdit").IsEnabled=!t.IsDeleted;foreach(string name in new[]{"DetailPending","DetailReview","DetailDone"})Find<Button>(name).IsEnabled=!t.IsDeleted;Find<Button>("DetailSaveReview").Visibility=t.IsAwaitingReview&&!t.IsDeleted?Visibility.Visible:Visibility.Collapsed;
  if(!String.IsNullOrEmpty(t.PlanningMeta)){var meta=CopyText(t.PlanningMeta,12,"AccentTextBrush");meta.Margin=new Thickness(0,0,0,12);detailExtra.Children.Add(meta);}
  if(t.IsDeleted){detailExtra.Children.Add(ActionButton("从回收站恢复",delegate{DeleteOrRestore(t);CloseOverlay(detailsPanel);SetMode("Agenda");},true));return;}
  var reviewSection=Section(detailExtra,"确认与跟进",t.IsAwaitingReview);reviewSection.Expanded+=delegate{Find<Button>("DetailSaveReview").Visibility=Visibility.Visible;};reviewSection.Collapsed+=delegate{Find<Button>("DetailSaveReview").Visibility=t.IsAwaitingReview?Visibility.Visible:Visibility.Collapsed;};var review=(StackPanel)reviewSection.Content;detailReviewerInput=Input(t.Reviewer);detailFollowUpInput=DateInput();SetDate(detailFollowUpInput,t.FollowUpDate);detailReviewNotesInput=Input(t.ReviewNotes,true);AddPair(review,"等待谁确认",detailReviewerInput,"下次跟进",detailFollowUpInput);AddField(review,"跟进备注",detailReviewNotesInput);
  var shortcuts=new WrapPanel{Margin=new Thickness(0,8,0,0)};foreach(int days in new[]{1,3,7}){int offset=days;shortcuts.Children.Add(ActionButton(offset+" 天后跟进",delegate{detailFollowUpInput.SelectedDate=DateTime.Today.AddDays(offset);}));}review.Children.Add(shortcuts);
  foreach(var entry in new[]{Tuple.Create("实际执行",t.ExecutedAt),Tuple.Create("提交确认",t.SubmittedAt),Tuple.Create("最终完成",t.CompletedAt)}){DateTime when;if(DateTime.TryParse(entry.Item2,out when)){var line=CopyText(entry.Item1+"  "+when.ToString("yyyy-MM-dd HH:mm"),11,"TextSecondaryBrush");line.Margin=new Thickness(0,7,0,0);detailExtra.Children.Add(line);}}
  if(t.Checklist.Count>0){var section=Section(detailExtra,"子清单 · "+t.Checklist.Count(x=>x.Done)+"/"+t.Checklist.Count,true);var list=(StackPanel)section.Content;foreach(ChecklistItem item in t.Checklist){var check=new CheckBox{Content=CopyText(item.Text,12),IsChecked=item.Done,Margin=new Thickness(0,9,0,3)};check.SetResourceReference(Control.ForegroundProperty,"TextPrimaryBrush");check.Click+=delegate{item.Done=check.IsChecked==true;t.RefreshPlanning();section.Header="子清单 · "+t.Checklist.Count(x=>x.Done)+"/"+t.Checklist.Count;mutationLabel="修改子清单";SaveTasks();};list.Children.Add(check);}}
  if(t.Links.Count>0){var links=(StackPanel)Section(detailExtra,"关联资料",true).Content;foreach(string link in t.Links){string target=link;var open=ActionButton(link,delegate{OpenTaskLink(target);});open.HorizontalContentAlignment=HorizontalAlignment.Left;open.ToolTip=link;links.Children.Add(open);}}
 }
 bool SaveDetailFollowUp(bool save){if(detailsTask==null||detailsTask.IsDeleted||detailReviewerInput==null)return false;DateTime parsed;if(!String.IsNullOrWhiteSpace(detailFollowUpInput.Text)&&!DateTime.TryParse(detailFollowUpInput.Text,out parsed)){MessageBox.Show("跟进日期无效，请从日历中选择。","检查日期");return false;}detailsTask.Reviewer=detailReviewerInput.Text.Trim();detailsTask.FollowUpDate=GetDate(detailFollowUpInput);detailsTask.ReviewNotes=detailReviewNotesInput.Text.Trim();detailsTask.FollowUpNotified="";detailsTask.RefreshPlanning();if(save){mutationLabel="更新跟进";SaveTasks();RefreshAll();workspaceStatus.Text="跟进信息已保存";}return true;}
 void OpenTaskLink(string target){try{Uri uri;if(Uri.TryCreate(target,UriKind.Absolute,out uri)&&(uri.Scheme=="https"||uri.Scheme=="http")){Process.Start(new ProcessStartInfo(target){UseShellExecute=true});return;}if(Directory.Exists(target)){Process.Start(new ProcessStartInfo("explorer.exe",'"'+target+'"'){UseShellExecute=true});return;}string ext=Path.GetExtension(target).ToLowerInvariant();if(new[]{".exe",".com",".bat",".cmd",".ps1",".vbs",".js",".lnk",".msi"}.Contains(ext))throw new InvalidOperationException("关联资料仅支持文档、文件夹与网页。");if(!File.Exists(target))throw new FileNotFoundException("找不到这个文件，请检查路径。");Process.Start(new ProcessStartInfo(target){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message,"打开关联资料");}}

 void ShowFilters(){OpenAux("筛选与保存视图");var category=Choices("全部分类","个人","工作","生活","重要");var project=Input(activeFilter==null?"":activeFilter.Project);var tags=Input(activeFilter==null?"":activeFilter.Tag);var priority=Choices("不限优先级","低及以上","中及以上","仅高优先级");if(activeFilter!=null){Select(category,activeFilter.Category??"全部分类");priority.SelectedIndex=activeFilter.MinimumPriority;}AddPair(auxBody,"分类",category,"优先级",priority);AddField(auxBody,"项目包含",project);AddField(auxBody,"标签包含",tags);var name=Input();AddField(auxBody,"保存名称（可选）",name);auxActions.Children.Add(ActionButton("应用筛选",delegate{var filter=new SavedTaskFilter{Name=name.Text.Trim(),Category=category.SelectedIndex==0?"":ComboText(category),Project=project.Text.Trim(),Tag=tags.Text.Trim(),MinimumPriority=priority.SelectedIndex};if(filter.Name.Length>0){savedFilters.RemoveAll(x=>x.Name==filter.Name);savedFilters.Add(filter);SaveFilterPreferences();RefreshFilterPicker();filterPicker.SelectedIndex=savedFilters.Count+2;}else activeFilter=filter;CloseOverlay(auxPanel);RefreshAll();},true));auxActions.Children.Add(ActionButton("清除筛选",delegate{activeFilter=null;filterPicker.SelectedIndex=0;CloseOverlay(auxPanel);RefreshAll();}));}
 void SaveFilterPreferences(){if(selfTest)return;File.WriteAllText(Path.Combine(folder,"planner-settings.json"),json.Serialize(new PlannerPreferences{Filters=savedFilters}),new UTF8Encoding(false));}

 void BuildWeekPanel(){weekStart=DateTime.Today.AddDays(-(((int)DateTime.Today.DayOfWeek+6)%7));weekPanel=new Grid{Visibility=Visibility.Collapsed};weekPanel.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});weekPanel.RowDefinitions.Add(new RowDefinition());var top=new WrapPanel();top.Children.Add(ActionButton("上一周",delegate{weekStart=weekStart.AddDays(-7);RenderWeek();}));top.Children.Add(ActionButton("本周",delegate{weekStart=DateTime.Today.AddDays(-(((int)DateTime.Today.DayOfWeek+6)%7));RenderWeek();}));top.Children.Add(ActionButton("下一周",delegate{weekStart=weekStart.AddDays(7);RenderWeek();}));top.Children.Add(ActionButton("更多视图",ShowViews));weekHeading=CopyText("",12,"TextSecondaryBrush");weekHeading.Margin=new Thickness(4,8,0,8);top.Children.Add(weekHeading);weekPanel.Children.Add(top);weekBody=new StackPanel();var scroll=new ScrollViewer{Content=weekBody,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);weekPanel.Children.Add(scroll);((Grid)agendaPanel.Parent).Children.Insert(0,weekPanel);}
 void ShowViews(){OpenAux("工具与视图");var links=new WrapPanel();auxBody.Children.Add(links);foreach(var pair in new[]{Tuple.Create("Agenda","日程"),Tuple.Create("Today","今天"),Tuple.Create("Calendar","月历"),Tuple.Create("Week","周计划"),Tuple.Create("Review","待确认"),Tuple.Create("Completed","已完成"),Tuple.Create("Inbox","收集箱"),Tuple.Create("Overdue","已逾期"),Tuple.Create("Focus","今日专注"),Tuple.Create("Recycle","回收站")}){var item=pair;links.Children.Add(ActionButton(item.Item2,delegate{CloseOverlay(auxPanel);SetMode(item.Item1);}));}var tools=new WrapPanel{Margin=new Thickness(0,15,0,0)};auxBody.Children.Add(tools);tools.Children.Add(ActionButton("快速添加",ShowQuickAdd));tools.Children.Add(ActionButton("筛选与保存视图",ShowFilters));tools.Children.Add(ActionButton("数据与恢复",ShowDataCenter));tools.Children.Add(ActionButton("专注计时",ShowFocusTimer));tools.Children.Add(ActionButton("收起为桌面胶囊",CollapseWorkspace));tools.Children.Add(ActionButton("贴靠屏幕右侧",delegate{CloseOverlay(auxPanel);DockWorkspace();}));}
 void RenderWeek(){
  if(weekBody==null)return;weekBody.Children.Clear();weekHeading.Text=weekStart.ToString("M月d日")+" — "+weekStart.AddDays(6).ToString("M月d日");
  int columns=window.ActualWidth>=1540?7:window.ActualWidth>=1000?3:window.ActualWidth>=660?2:1;
  var days=new Grid();for(int c=0;c<columns;c++)days.ColumnDefinitions.Add(new ColumnDefinition());for(int r=0;r<(7+columns-1)/columns;r++)days.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});weekBody.Children.Add(days);
  for(int i=0;i<7;i++){
   DateTime day=weekStart.AddDays(i);var body=new StackPanel();var shell=InputFrame(body);shell.Padding=new Thickness(12);shell.Margin=new Thickness(2,0,6,10);shell.AllowDrop=true;shell.Drop+=delegate(object sender,DragEventArgs e){DropOnDate(e,day);};Grid.SetRow(shell,i/columns);Grid.SetColumn(shell,i%columns);
   var row=new DockPanel();var add=ActionButton("添加",delegate{ShowEditor(null);editDate.SelectedDate=day;});DockPanel.SetDock(add,Dock.Right);row.Children.Add(add);var title=CopyText(day.ToString("M月d日")+" · 周"+"一二三四五六日"[((int)day.DayOfWeek+6)%7],13,day==DateTime.Today?"AccentTextBrush":"TextPrimaryBrush");title.FontWeight=FontWeights.SemiBold;row.Children.Add(title);body.Children.Add(row);
   var entries=tasks.Where(t=>PlanningRules.Occurs(t,day)&&MatchesWorkspaceQuery(t)).OrderBy(t=>t.DueTime).ThenBy(t=>t.SortOrder).ToList();
   int effort=entries.Where(x=>!x.IsDone).Sum(x=>DailyEstimate(x));body.Children.Add(CopyText(entries.Count+" 项 · 预计 "+effort+" 分钟",10.5,"TextSecondaryBrush"));
   if(entries.Count==0){var empty=CopyText("留一点空白，也可以拖入安排",11,"TextSecondaryBrush");empty.Margin=new Thickness(0,12,0,9);body.Children.Add(empty);}
   foreach(var task in entries){TaskItem captured=task;var content=new StackPanel();var name=CopyText((task.DueDate!=day.ToString("yyyy-MM-dd")?"延续":task.DueTime.Length==0?"全天":task.DueTime)+"  "+task.Title,12);if(task.IsDone)name.TextDecorations=TextDecorations.Strikethrough;content.Children.Add(name);content.Children.Add(CopyText(task.StatusText+(String.IsNullOrEmpty(task.DeadlineDate)?"":" · 截止 "+task.DeadlineDate),10.5,"TextSecondaryBrush"));var button=ActionButton("",delegate{if(!dragConsumed)ShowDetails(captured);});button.Content=content;button.Padding=new Thickness(0);button.HorizontalContentAlignment=HorizontalAlignment.Stretch;button.HorizontalAlignment=HorizontalAlignment.Stretch;button.Margin=new Thickness(0,8,0,0);button.PreviewMouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){dragStart=e.GetPosition(window);dragTask=captured;};button.PreviewMouseMove+=DragTaskMove;body.Children.Add(button);}days.Children.Add(shell);
  }
 }
 static int DailyEstimate(TaskItem t){DateTime start,end;if(PlanningRules.TryDate(t.DueDate,out start)&&PlanningRules.TryDate(t.EndDate,out end)&&end>=start)return (int)Math.Ceiling((double)t.EstimateMinutes/((end-start).Days+1));return t.EstimateMinutes;}
 void HookTaskDrag(ListBox list){list.PreviewMouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){DependencyObject source=e.OriginalSource as DependencyObject;if(Parent<CheckBox>(source)!=null||Parent<Button>(source)!=null)return;var row=Parent<ListBoxItem>(source);dragTask=row==null?null:row.DataContext as TaskItem;if(dragTask==null&&row!=null&&row.DataContext is DayEntry)dragTask=((DayEntry)row.DataContext).Task;dragStart=e.GetPosition(window);};list.PreviewMouseMove+=DragTaskMove;}
 void DragTaskMove(object sender,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed||dragTask==null||dragTask.IsDeleted)return;Point p=e.GetPosition(window);if(Math.Abs(p.X-dragStart.X)+Math.Abs(p.Y-dragStart.Y)<8)return;TaskItem task=dragTask;dragTask=null;dragConsumed=true;DragDrop.DoDragDrop((DependencyObject)sender,new DataObject("LumiTaskId",task.Id),DragDropEffects.Move);RunLater(50,delegate{dragConsumed=false;});}
 void DropOnTask(object sender,DragEventArgs e){if(!e.Data.GetDataPresent("LumiTaskId"))return;var row=Parent<ListBoxItem>(e.OriginalSource as DependencyObject);TaskItem target=row==null?null:row.DataContext as TaskItem;TaskItem source=tasks.FirstOrDefault(x=>x.Id==Convert.ToString(e.Data.GetData("LumiTaskId")));if(source==null||target==null||source==target||target.IsDeleted)return;Reschedule(source,target.DueDate);var order=tasks.Where(x=>!x.IsDeleted&&x.DueDate==target.DueDate&&x!=source).OrderBy(x=>x.SortOrder).ThenBy(x=>x.DueTime).ToList();order.Insert(Math.Max(0,order.IndexOf(target)),source);for(int i=0;i<order.Count;i++)order[i].SortOrder=i;mutationLabel="拖动排序与改期";SaveTasks();RefreshAll();e.Handled=true;}
 void DropOnDate(DragEventArgs e,DateTime day){if(!e.Data.GetDataPresent("LumiTaskId"))return;TaskItem task=tasks.FirstOrDefault(x=>x.Id==Convert.ToString(e.Data.GetData("LumiTaskId")));if(task==null||task.IsDeleted)return;Reschedule(task,day.ToString("yyyy-MM-dd"));mutationLabel="拖动调整计划";SaveTasks();RefreshAll();e.Handled=true;}
 readonly HashSet<CalendarDayButton> calendarDropHooks=new HashSet<CalendarDayButton>();
 void HookCalendarDrop(CalendarDayButton cell){if(!calendarDropHooks.Add(cell))return;cell.AllowDrop=true;cell.Drop+=delegate(object sender,DragEventArgs e){if(cell.DataContext is DateTime)DropOnDate(e,(DateTime)cell.DataContext);};}
 void Reschedule(TaskItem task,string date){DateTime old,end,newDate;if(PlanningRules.TryDate(task.DueDate,out old)&&PlanningRules.TryDate(task.EndDate,out end)&&PlanningRules.TryDate(date,out newDate))task.EndDate=end.Add(newDate-old).ToString("yyyy-MM-dd");task.DueDate=date;task.Unscheduled=false;task.Notified="";task.RefreshPlanning();}
 void RefreshAll(){foreach(TaskItem t in tasks)t.RefreshPlanning();view.Refresh();RefreshDay();UpdateSummary();RefreshWorkspace();}

 void ShowDataCenter(){OpenAux("数据与恢复");auxBody.Children.Add(CopyText("日程、跟进与子清单只保存在本机。导出包含回收站；导入会先检查内容，再显示合并选项。",12,"TextSecondaryBrush"));var actions=new WrapPanel{Margin=new Thickness(0,14,0,8)};actions.Children.Add(ActionButton("导出全部日程",ExportTasks));actions.Children.Add(ActionButton("导入 JSON",ImportTasks));actions.Children.Add(ActionButton("立即备份",delegate{try{if(selfTest)return;string p=BackupVault.Capture(taskPath,true);workspaceStatus.Text=p==null?"暂无任务文件可备份":"已创建恢复点";ShowDataCenter();}catch(Exception ex){MessageBox.Show(ex.Message,"备份失败");}}));auxBody.Children.Add(actions);auxBody.Children.Add(CopyText("历史恢复点",15));auxBody.Children.Add(CopyText("自动备份保留近小时与不同日期的版本。恢复前会再备份当前数据，也可以使用撤销恢复本次操作。",11,"TextSecondaryBrush"));foreach(string path in BackupVault.List(taskPath).Take(30)){string captured=path;var restore=ActionButton(File.GetLastWriteTime(path).ToString("yyyy-MM-dd HH:mm:ss")+"  ·  预览恢复",delegate{PreviewRestore(captured);});restore.HorizontalContentAlignment=HorizontalAlignment.Left;auxBody.Children.Add(restore);}if(!BackupVault.List(taskPath).Any())auxBody.Children.Add(CopyText("还没有历史恢复点；首次保存已有任务文件时会自动创建。",12,"TextSecondaryBrush"));}
 void ExportTasks(){var dialog=new Microsoft.Win32.SaveFileDialog{Title="导出日程",Filter="JSON 日程文件|*.json",FileName="流光日程-"+DateTime.Today.ToString("yyyyMMdd")+".json"};if(dialog.ShowDialog(window)!=true)return;try{File.WriteAllText(dialog.FileName,SerializeTasks(),new UTF8Encoding(false));workspaceStatus.Text="日程已导出";}catch(Exception ex){MessageBox.Show(ex.Message,"导出失败");}}
 void ImportTasks(){var dialog=new Microsoft.Win32.OpenFileDialog{Title="导入日程",Filter="JSON 日程文件|*.json"};if(dialog.ShowDialog(window)!=true)return;try{var incoming=TaskStorage.Read(dialog.FileName);foreach(var task in incoming){string error=PlanningRules.Validate(task);if(error!=null)throw new InvalidDataException(error+"："+task.Title);}if(incoming.GroupBy(x=>x.Id).Any(x=>x.Count()>1))throw new InvalidDataException("导入文件中有重复 ID，请先检查文件。");OpenAux("预览导入 · "+incoming.Count+" 项");int duplicate=incoming.Count(x=>tasks.Any(t=>t.Id==x.Id));auxBody.Children.Add(CopyText("新日程 "+(incoming.Count-duplicate)+" 项，同 ID 日程 "+duplicate+" 项。默认保留本机同 ID 记录。"));var overwrite=new CheckBox{Content="使用导入内容替换同 ID 日程",Margin=new Thickness(0,12,0,8)};overwrite.SetResourceReference(Control.ForegroundProperty,"TextPrimaryBrush");auxBody.Children.Add(overwrite);foreach(var t in incoming.Take(12))auxBody.Children.Add(CopyText(t.Title+" · "+t.StatusText,11,"TextSecondaryBrush"));auxActions.Children.Add(ActionButton("确认合并导入",delegate{var list=tasks.ToDictionary(x=>x.Id,x=>x);foreach(var t in incoming){if(!list.ContainsKey(t.Id)||overwrite.IsChecked==true)list[t.Id]=t;}ReplaceInMemory(list.Values);mutationLabel="导入日程";SaveTasks();CloseOverlay(auxPanel);RefreshAll();},true));}catch(Exception ex){MessageBox.Show("未导入任何内容："+ex.Message,"导入失败");}}
 void PreviewRestore(string path){try{var replacement=TaskStorage.Read(path);OpenAux("预览恢复");auxBody.Children.Add(CopyText(File.GetLastWriteTime(path).ToString("yyyy-MM-dd HH:mm:ss")+" 的恢复点，共 "+replacement.Count+" 项。确认后将替换当前日程。",12));foreach(var t in replacement.Take(15))auxBody.Children.Add(CopyText(t.Title+" · "+t.StatusText,11,"TextSecondaryBrush"));auxActions.Children.Add(ActionButton("备份当前并恢复此版本",delegate{try{if(!selfTest)BackupVault.Capture(taskPath,true);ReplaceInMemory(replacement);mutationLabel="恢复历史备份";SaveTasks();CloseOverlay(auxPanel);SetMode("Agenda");}catch(Exception ex){MessageBox.Show(ex.Message,"恢复失败");}},true));}catch(Exception ex){MessageBox.Show("这个恢复点无法读取："+ex.Message,"无法恢复");}}

 void WorkspaceKeys(object sender,KeyEventArgs e){if(e.Key==Key.Escape){HideOverlays();return;}if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.N){e.Handled=true;ShowQuickAdd();return;}bool editingText=Keyboard.FocusedElement is TextBox||Keyboard.FocusedElement is System.Windows.Controls.Primitives.TextBoxBase;if(editingText)return;if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.Z){e.Handled=true;ReplayHistory(false);}if(Keyboard.Modifiers==ModifierKeys.Control&&e.Key==Key.Y){e.Handled=true;ReplayHistory(true);}}
 void ShowFocusTimer(){OpenAux("专注计时");auxBody.Children.Add(CopyText("给这一段工作留出完整的时间。计时只在本程序运行时有效。",12,"TextSecondaryBrush"));var minutes=Input("25");AddField(auxBody,"本次专注分钟",minutes);auxActions.Children.Add(ActionButton("开始专注",delegate{int duration;if(!Int32.TryParse(minutes.Text,out duration)||duration<1||duration>240){auxHeading.Text="请输入 1–240 分钟";return;}if(focusTimer!=null)focusTimer.Stop();focusPaused=false;focusEnds=DateTime.Now.AddMinutes(duration);focusTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};focusTimer.Tick+=delegate{if(focusPaused)return;focusRemaining=focusEnds-DateTime.Now;if(focusRemaining<=TimeSpan.Zero){focusTimer.Stop();focusTimer=null;workspaceStatus.Text="本次专注已完成，休息一下";if(notifyIcon!=null){notifyIcon.BalloonTipTitle="专注完成";notifyIcon.BalloonTipText="这一段工作告一段落，起来活动一下。";notifyIcon.ShowBalloonTip(5000);}return;}workspaceStatus.Text="专注中  "+focusRemaining.ToString(@"mm\:ss")+" · 工具中可暂停";};focusTimer.Start();CloseOverlay(auxPanel);SetMode("Focus");},true));if(focusTimer!=null){auxActions.Children.Add(ActionButton(focusPaused?"继续":"暂停",delegate{if(!focusPaused){focusRemaining=focusEnds-DateTime.Now;focusPaused=true;workspaceStatus.Text="专注已暂停";}else{focusEnds=DateTime.Now+focusRemaining;focusPaused=false;}CloseOverlay(auxPanel);}));auxActions.Children.Add(ActionButton("结束计时",delegate{focusTimer.Stop();focusTimer=null;CloseOverlay(auxPanel);RefreshWorkspace();}));}}
 void InstallTrayActions(){if(notifyIcon==null)return;var menu=new Forms.ContextMenuStrip();menu.Items.Add("打开日程",null,delegate{RestoreWorkspace();});menu.Items.Add("快速添加 (Ctrl+Alt+N)",null,delegate{ShowQuickAdd();});menu.Items.Add("收起为桌面胶囊",null,delegate{CollapseWorkspace();});menu.Items.Add("提醒稍后 15 分钟",null,delegate{foreach(var task in tasks.Where(x=>lastReminderIds.Contains(x.Id))){task.ReminderSnoozeUntil=DateTime.Now.AddMinutes(15).ToString("o");task.Notified="";}mutationLabel="稍后提醒";SaveTasks();});menu.Items.Add("退出",null,delegate{window.Close();});notifyIcon.ContextMenuStrip=menu;notifyIcon.BalloonTipClicked+=delegate{RestoreWorkspace();SetMode(lastBalloonIsFollowUp?"Review":"Today");};}
 void CheckFollowUps(){if(selfTest||notifyIcon==null)return;string today=DateTime.Today.ToString("yyyy-MM-dd");var waiting=tasks.Where(x=>!x.IsDeleted&&x.IsAwaitingReview&&PlanningRules.IsDateBefore(x.FollowUpDate,DateTime.Today.AddDays(1))&&x.FollowUpNotified!=today).ToList();if(waiting.Count==0)return;foreach(var t in waiting)t.FollowUpNotified=today;SaveTasks();lastBalloonIsFollowUp=true;notifyIcon.BalloonTipTitle="待确认工作需要跟进";notifyIcon.BalloonTipText=waiting.Count==1?waiting[0].Title+" · "+(waiting[0].Reviewer??"等待确认"):waiting.Count+" 项工作到了跟进日期";notifyIcon.ShowBalloonTip(8000);}
 void ClampToScreen(){var screen=Forms.Screen.FromHandle(new WindowInteropHelper(window).Handle);var transform=PresentationSource.FromVisual(window).CompositionTarget.TransformFromDevice;var corner=transform.Transform(new Point(screen.WorkingArea.Left,screen.WorkingArea.Top));var end=transform.Transform(new Point(screen.WorkingArea.Right,screen.WorkingArea.Bottom));window.Left=Math.Max(corner.X,Math.Min(window.Left,end.X-window.ActualWidth));window.Top=Math.Max(corner.Y,Math.Min(window.Top,end.Y-window.ActualHeight));}
 void DockWorkspace(){var screen=Forms.Screen.FromHandle(new WindowInteropHelper(window).Handle);var transform=PresentationSource.FromVisual(window).CompositionTarget.TransformFromDevice;var bottomRight=transform.Transform(new Point(screen.WorkingArea.Right,screen.WorkingArea.Bottom));window.Left=bottomRight.X-window.ActualWidth-12;ClampToScreen();}
 void CollapseWorkspace(){if(capsule!=null){capsule.Activate();return;}HideOverlays();expandedWidth=window.Width;expandedHeight=window.Height;capsule=new Window{Title="流光日程 · 桌面胶囊",Width=278,Height=72,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,Topmost=window.Topmost,Left=window.Left,Top=window.Top};capsule.Resources.MergedDictionaries.Add(window.Resources);var body=new Grid();var border=InputFrame(body);RenderOptions.SetClearTypeHint(border,ClearTypeHint.Enabled);ApplyTextMode(border);border.CornerRadius=new CornerRadius(20);border.Padding=new Thickness(13,9,8,9);border.SetResourceReference(Border.BackgroundProperty,"PanelBrush");capsule.Content=border;body.ColumnDefinitions.Add(new ColumnDefinition());body.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var content=new StackPanel();content.Children.Add(CopyText("流光日程",14));content.Children.Add(CopyText(tasks.Count(x=>!x.IsDeleted&&!x.IsDone&&!x.IsAwaitingReview)+" 项待办 · "+tasks.Count(x=>!x.IsDeleted&&x.IsAwaitingReview)+" 项待确认",11,"TextSecondaryBrush"));content.MouseLeftButtonDown+=delegate{capsule.DragMove();};body.Children.Add(content);var open=ActionButton("展开",RestoreWorkspace);Grid.SetColumn(open,1);body.Children.Add(open);capsule.Closed+=delegate{capsule=null;if(!closingWorkspace)window.Show();};capsule.DpiChanged+=delegate{double s=VisualTreeHelper.GetDpi(capsule).DpiScaleX;TextOptions.SetTextFormattingMode(border,s<=1.05?TextFormattingMode.Display:TextFormattingMode.Ideal);};capsule.Show();window.Hide();}
 void RestoreWorkspace(){if(capsule!=null){var old=capsule;capsule=null;old.Close();}if(window==null)return;window.Show();if(window.WindowState==WindowState.Minimized)window.WindowState=WindowState.Normal;window.Activate();}
}
